def _type_ok(value, name):
    if name == "object":
        return isinstance(value, dict)
    if name == "array":
        return isinstance(value, list)
    if name == "string":
        return isinstance(value, str)
    if name == "boolean":
        return isinstance(value, bool)
    if isinstance(value, bool):
        return False
    if name == "integer":
        return isinstance(value, int)
    if name == "number":
        return isinstance(value, (int, float))
    return True


def validate(value, schema, path="$"):
    if "type" in schema and not _type_ok(value, schema["type"]):
        return [path]
    errors = []
    if "enum" in schema and value not in schema["enum"]:
        errors.append(path)
    elif "minimum" in schema and value < schema["minimum"]:
        errors.append(path)
    elif "maximum" in schema and value > schema["maximum"]:
        errors.append(path)
    if isinstance(value, dict):
        props = schema.get("properties", {})
        for key in schema.get("required", []):
            if key not in value:
                errors.append(path + "." + key)
        for key, item in value.items():
            if key in props:
                errors.extend(validate(item, props[key], path + "." + key))
            elif schema.get("additionalProperties", True) is False:
                errors.append(path + "." + key)
    if isinstance(value, list) and "items" in schema:
        for i, item in enumerate(value):
            errors.extend(validate(item, schema["items"], f"{path}[{i}]"))
    return errors

prompt.en:
Retry math assumes independent attempts. Real failures cluster on hard inputs. Write `retry_success(p_easy, p_hard, hard_share, attempts)` that returns the probability that a request succeeds within `attempts` tries when:

- a share `hard_share` of inputs is hard and each attempt on them succeeds with probability `p_hard`;
- the rest are easy and each attempt succeeds with probability `p_easy`;
- attempts are independent **within** each group.

prompt.es:
Las cuentas de los reintentos suponen intentos independientes. Los fallos reales se agrupan en las entradas difíciles. Escribe `retry_success(p_easy, p_hard, hard_share, attempts)`, que devuelve la probabilidad de que una petición tenga éxito en `attempts` intentos cuando:

- una proporción `hard_share` de las entradas es difícil y cada intento sobre ellas acierta con probabilidad `p_hard`;
- el resto son fáciles y cada intento acierta con probabilidad `p_easy`;
- los intentos son independientes **dentro** de cada grupo.
